#include <functional>
#include <cstdint>
#include <sys/epoll.h>

class EventLoop;

/// @brief 事件通道，封装文件描述符及其关注的事件和回调
///        是 Reactor 模式中 Event 和 Handler 的桥梁
class Channel {
public:
    using EventCallback = std::function<void()>;

    Channel(EventLoop* loop, int fd);
    ~Channel();

    // 禁止拷贝
    Channel(const Channel&) = delete;
    Channel& operator=(const Channel&) = delete;

    /// @brief 处理事件（由 EventLoop 在 poll 返回后调用）
    void handleEvent() const;

    /// @brief 设置各事件的回调
    void setReadCallback(EventCallback cb)  { read_cb_  = std::move(cb); }
    void setWriteCallback(EventCallback cb) { write_cb_ = std::move(cb); }
    void setCloseCallback(EventCallback cb) { close_cb_ = std::move(cb); }
    void setErrorCallback(EventCallback cb) { error_cb_ = std::move(cb); }

    int fd() const { return fd_; }
    uint32_t events() const { return events_; }
    void setRevents(uint32_t revt) { revents_ = revt; }

    /// @brief 启用/禁用读事件
    void enableReading();
    void disableReading();
    /// @brief 启用/禁用写事件
    void enableWriting();
    void disableWriting();
    /// @brief 禁用所有事件
    void disableAll();

    bool isNoneEvent() const { return events_ == kNoneEvent; }
    bool isWriting() const { return events_ & kWriteEvent; }

    /// @brief 将 Channel 从 EventLoop 中移除
    void remove();

private:
    void update();

    static constexpr uint32_t kNoneEvent  = 0;
    static constexpr uint32_t kReadEvent  = EPOLLIN | EPOLLPRI;
    static constexpr uint32_t kWriteEvent = EPOLLOUT;

    EventLoop* owner_loop_;
    const int fd_;
    uint32_t events_;   // 关注的事件
    uint32_t revents_;  // 实际就绪的事件

    EventCallback read_cb_;
    EventCallback write_cb_;
    EventCallback close_cb_;
    EventCallback error_cb_;
};", "old_string": ""}

