class Channel;
class EpollPoller;

/// @brief 事件循环，Reactor 模式的核心
///        负责驱动 epoll 轮询并分发事件到各个 Channel
class EventLoop {
public:
    using Functor = std::function<void()>;

    EventLoop();
    ~EventLoop();

    // 禁止拷贝
    EventLoop(const EventLoop&) = delete;
    EventLoop& operator=(const EventLoop&) = delete;

    /// @brief 开始事件循环（主循环）
    void loop();

    /// @brief 退出事件循环
    void quit();

    /// @brief 在 I/O 线程中执行回调（跨线程调用安全）
    void runInLoop(Functor cb);

    /// @brief 将回调排入队列，等待 I/O 线程执行
    void queueInLoop(Functor cb);

    /// @brief 更新 Channel 的关注事件
    void updateChannel(Channel* channel);

    /// @brief 移除 Channel
    void removeChannel(Channel* channel);

    /// @brief 判断是否在当前事件循环线程
    bool isInLoopThread() const;

private:
    void wakeup();              // 唤醒阻塞在 epoll_wait 上的事件循环
    void handleRead();          // 处理 wakeup fd 的读事件
    void doPendingFunctors();   // 执行队列中的待处理回调

    std::atomic<bool> looping_;
    std::atomic<bool> quit_;
    std::atomic<bool> calling_pending_functors_;

    std::unique_ptr<EpollPoller> poller_;
    int wakeup_fd_;  // eventfd，用于跨线程唤醒
    std::unique_ptr<Channel> wakeup_channel_;

    std::vector<Functor> pending_functors_;
    std::mutex mutex_;

    pid_t thread_id_;  // 记录事件循环所属线程
};", "old_string": ""}

