#include <vector>
#include <string>
#include <cstring>
#include <algorithm>
#include <cstddef>
#include <sys/types.h>

/// @brief 应用层缓冲区，用于非阻塞 I/O 的读写缓冲
///        布局: [已读区域 | 可读区域 | 可写区域]
///               0      readerIndex_  writerIndex_  size()
class Buffer {
public:
    static constexpr size_t kCheapPrepend = 8;   // 预留空间
    static constexpr size_t kInitialSize = 1024;

    explicit Buffer(size_t initial_size = kInitialSize)
        : buffer_(kCheapPrepend + initial_size),
          reader_index_(kCheapPrepend),
          writer_index_(kCheapPrepend) {}

    /// @brief 可读字节数
    size_t readableBytes() const { return writer_index_ - reader_index_; }

    /// @brief 可写字节数
    size_t writableBytes() const { return buffer_.size() - writer_index_; }

    /// @brief 前方可读空间字节数
    size_t prependableBytes() const { return reader_index_; }

    /// @brief 返回可读数据的起始指针
    const char* peek() const { return begin() + reader_index_; }

    /// @brief 确保有足够的可写空间
    void ensureWritableBytes(size_t len) {
        if (writableBytes() < len) {
            makeSpace(len);
        }
    }

    /// @brief 向缓冲区追加数据
    void append(const char* data, size_t len) {
        ensureWritableBytes(len);
        std::copy(data, data + len, beginWrite());
        writer_index_ += len;
    }

    void append(const std::string& str) {
        append(str.data(), str.size());
    }

    /// @brief 返回可写区域起始位置
    char* beginWrite() { return begin() + writer_index_; }
    const char* beginWrite() const { return begin() + writer_index_; }

    /// @brief 从缓冲区消费 len 字节
    void retrieve(size_t len) {
        reader_index_ += len;
    }

    /// @brief 读取数据到字符串并清空
    std::string retrieveAsString(size_t len) {
        std::string result(peek(), len);
        retrieve(len);
        return result;
    }

    std::string retrieveAllAsString() {
        return retrieveAsString(readableBytes());
    }

    /// @brief 从 fd 读取数据到缓冲区
    ssize_t readFd(int fd, int* saved_errno);

    /// @brief 将缓冲区数据写入 fd
    ssize_t writeFd(int fd, int* saved_errno);

private:
    char* begin() { return &*buffer_.begin(); }
    const char* begin() const { return &*buffer_.begin(); }

    void makeSpace(size_t len) {
        if (writableBytes() + prependableBytes() < len + kCheapPrepend) {
            buffer_.resize(writer_index_ + len);
        } else {
            // 搬移已读数据，腾出写空间
            size_t readable = readableBytes();
            std::copy(begin() + reader_index_, begin() + writer_index_,
                      begin() + kCheapPrepend);
            reader_index_ = kCheapPrepend;
            writer_index_ = reader_index_ + readable;
        }
    }

    std::vector<char> buffer_;
    size_t reader_index_;
    size_t writer_index_;
};", "old_string": ""}

