#include <memory>
#include <string>
#include <functional>
#include <atomic>

class EventLoop;
class Channel;
class Buffer;

/// @brief TCP 连接封装，管理单个客户端连接的生命周期
///        使用 shared_ptr 管理，支持连接断开后的安全释放
class TcpConnection : public std::enable_shared_from_this<TcpConnection> {
public:
    using TcpConnectionPtr = std::shared_ptr<TcpConnection>;
    using ConnectionCallback = std::function<void(const TcpConnectionPtr&)>;
    using MessageCallback = std::function<void(const TcpConnectionPtr&, Buffer*)>;
    using CloseCallback = std::function<void(const TcpConnectionPtr&)>;

    TcpConnection(EventLoop* loop, const std::string& name, int sockfd);
    ~TcpConnection();

    // 禁止拷贝
    TcpConnection(const TcpConnection&) = delete;
    TcpConnection& operator=(const TcpConnection&) = delete;

    EventLoop* getLoop() const { return loop_; }
    const std::string& name() const { return name_; }
    bool connected() const { return state_ == kConnected; }

    /// @brief 发送数据到对端
    void send(const std::string& message);

    /// @brief 主动关闭连接
    void shutdown();

    /// @brief 启动连接（注册到 EventLoop）
    void establishConnection();

    /// @brief 设置回调
    void setConnectionCallback(ConnectionCallback cb) { connection_cb_ = std::move(cb); }
    void setMessageCallback(MessageCallback cb) { message_cb_ = std::move(cb); }
    void setCloseCallback(CloseCallback cb) { close_cb_ = std::move(cb); }

    /// @brief 获取输入缓冲区
    Buffer* inputBuffer() { return input_buffer_.get(); }
    /// @brief 获取输出缓冲区
    Buffer* outputBuffer() { return output_buffer_.get(); }

private:
    enum State { kDisconnected, kConnecting, kConnected, kDisconnecting };

    void handleRead();
    void handleWrite();
    void handleClose();
    void handleError();
    void sendInLoop(const std::string& message);
    void shutdownInLoop();

    EventLoop* loop_;
    std::string name_;
    std::atomic<State> state_;
    std::unique_ptr<Channel> channel_;
    std::unique_ptr<Buffer> input_buffer_;
    std::unique_ptr<Buffer> output_buffer_;

    ConnectionCallback connection_cb_;
    MessageCallback message_cb_;
    CloseCallback close_cb_;
};", "old_string": ""}

